def step(state, s):
    if state == 'NORMAL':
        if s.get('fault_candidate'):
            return 'SUSPECT'
    elif state == 'SUSPECT':
        if s.get('fault_persisted'):
            return 'FAULT_LATCHED'
        if s.get('fault_cleared'):
            return 'NORMAL'
    elif state == 'FAULT_LATCHED':
        if s.get('clear_requested') and s.get('safe_to_clear'):
            return 'RECOVERY_CHECK'
    elif state == 'RECOVERY_CHECK':
        if s.get('checks_passed'):
            return 'NORMAL'
    return state

def step(state, s):
    if state == 'READY':
        if s.get('ignition_on'):
            return 'MONITORING'
    elif state == 'MONITORING':
        if s.get('slip_confirmed'):
            return 'FAULT_LATCHED'
        if s.get('ignition_off') and not s.get('slip_confirmed'):
            return 'READY'
    elif state == 'FAULT_LATCHED':
        if s.get('clear_requested') and s.get('vehicle_speed') == 0:
            return 'READY'
    elif state == 'RECOVERY_CHECK':
        if s.get('self_test_ok') and s.get('fault_absent'):
            return 'READY'
        if not s.get('self_test_ok') or s.get('fault_present'):
            return 'FAULT_LATCHED'
    return state

def step(state, s):
    if state == 'IDLE':
        if s.get('start_requested'):
            return 'MONITORING'
    elif state == 'MONITORING':
        if s.get('fault_confirmed'):
            return 'FAULT_LATCHED'
        if s.get('stop_requested') and not s.get('fault_confirmed'):
            return 'IDLE'
    elif state == 'FAULT_LATCHED':
        if s.get('clear_requested') and s.get('vehicle_stationary'):
            return 'RECOVERY_CHECK'
    elif state == 'RECOVERY_CHECK':
        if s.get('self_test_ok') and s.get('fault_absent'):
            return 'IDLE'
        return 'FAULT_LATCHED'
    return state
